<?php
namespace App\Http\Controllers;use App\Models\{AdmissionCampaign,Program,Document};class AdmissionController extends Controller{public function __invoke(){$campaign=AdmissionCampaign::where('is_active',true)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',today()))->orderByRaw("CASE status WHEN 'open' THEN 0 WHEN 'results' THEN 1 WHEN 'planned' THEN 2 ELSE 3 END")->latest('starts_at')->first();return view('admission.index',['campaign'=>$campaign,'programs'=>Program::with('department')->where('is_active',true)->orderBy('sort')->get(),'documents'=>Document::where('is_published',true)->where(fn($q)=>$q->whereIn('category',['Документы','Образование'])->orWhere('category','like','%Приём%'))->where(fn($q)=>$q->where('title','like','%прием%')->orWhere('title','like','%приём%')->orWhere('title','like','%заявлен%')->orWhere('title','like','%вступ%'))->orderBy('sort')->get()]);}}